CountDownLatch latch = new CountDownLatch(3);
ExecutorService pool = Executors.newFixedThreadPool(3);
for (int i=0;i<3;i++) pool.submit(() -> { try { Thread.sleep(50+new Random().nextInt(100)); } catch (Exception e) {} finally { latch.countDown(); } });
System.out.println("czekam...");
latch.await(5, TimeUnit.SECONDS);
System.out.println("wszyscy gotowi!");
pool.shutdown(); pool.awaitTermination(5, TimeUnit.SECONDS);

CountDownLatch latch = new CountDownLatch(5);
for (int i=1;i<=5;i++) { int id=i; new Thread(() -> { try { Thread.sleep(100+new Random().nextInt(200)); System.out.println("watek-"+id); } catch (Exception e) {} finally { latch.countDown(); } }).start(); }
boolean ok = latch.await(3, TimeUnit.SECONDS);
System.out.println(ok);

