ExecutorService pool = Executors.newFixedThreadPool(4);
CountDownLatch latch = new CountDownLatch(6);
int[] czasy = {50,90,130,170,210,250};
for (int c : czasy) pool.submit(() -> { try { Thread.sleep(c); } catch (Exception e) {} finally { latch.countDown(); } });
long t0 = System.nanoTime();
latch.await(5, TimeUnit.SECONDS);
System.out.println((System.nanoTime()-t0)/1_000_000 + "ms");
pool.shutdown(); pool.awaitTermination(5, TimeUnit.SECONDS);

AtomicInteger round = new AtomicInteger(0);
CyclicBarrier barrier = new CyclicBarrier(4, () -> { int r = round.incrementAndGet(); System.out.println("runda "+r); });
Thread[] t = new Thread[4];
for (int i=0;i<4;i++) t[i] = new Thread(() -> { try { for (int r=0;r<3;r++) barrier.await(); } catch (Exception e) {} });
for (Thread th : t) th.start();
for (Thread th : t) th.join(5_000);
System.out.println(round.get() == 3);

Semaphore semaphore = new Semaphore(2);
AtomicInteger activeNow = new AtomicInteger(0);
for (int i=1;i<=6;i++) { int id=i; new Thread(() -> { try { semaphore.acquire(); int aktywne = activeNow.incrementAndGet(); System.out.println("aktywne="+aktywne); Thread.sleep(100); activeNow.decrementAndGet(); } catch (Exception e) {} finally { semaphore.release(); } }).start(); }

