for (int i=0;i<3;i++) new Thread(() -> { try { for (int r=0;r<2;r++) { sharedCounter.addAndGet(2); barrier.await(); } } catch (Exception e) {} }).start();

CountDownLatch latchA = new CountDownLatch(2);
CountDownLatch latchB = new CountDownLatch(3);
for (int i=0;i<2;i++) new Thread(() -> { try { Thread.sleep(100); } catch (Exception e) {} finally { latchA.countDown(); } }).start();
for (int i=0;i<3;i++) new Thread(() -> { try { Thread.sleep(150); } catch (Exception e) {} finally { latchB.countDown(); } }).start();
