Semaphore mutex = new Semaphore(1);
int[] counter = {0};
Thread[] t = new Thread[8];
for (int i=0;i<8;i++) t[i] = new Thread(() -> { for (int j=0;j<500;j++) { try { mutex.acquire(); counter[0]++; } catch (Exception e) {} finally { mutex.release(); } } });
for (Thread th : t) th.start();
for (Thread th : t) th.join(10_000);
System.out.println(counter[0] == 4000);

CountDownLatch startGate = new CountDownLatch(1);
CountDownLatch finishGate = new CountDownLatch(5);
AtomicInteger miejsce = new AtomicInteger(0);
for (int i=1;i<=5;i++) { int id=i; new Thread(() -> { try { startGate.await(); Thread.sleep(100+new Random().nextInt(300)); System.out.println("biegacz-"+id+": miejsce "+miejsce.incrementAndGet()); } catch (Exception e) {} finally { finishGate.countDown(); } }).start(); }
