finishGate.await(5, TimeUnit.SECONDS);

AtomicInteger total = new AtomicInteger(0);
CyclicBarrier barrier = new CyclicBarrier(4);
Thread[] t = new Thread[4];
for (int i=0;i<4;i++) { int id=i+1; t[i] = new Thread(() -> { try { for (int etap=0;etap<3;etap++) { total.addAndGet(id); barrier.await(); } } catch (Exception e) {} }); }
for (Thread th : t) th.start();
for (Thread th : t) th.join(5_000);
System.out.println(total.get() == 30);

Semaphore semaphore = new Semaphore(3);
ExecutorService pool = Executors.newFixedThreadPool(10);
List<Future<String>> futures = new ArrayList<>();
for (int i=1;i<=10;i++) { int id=i; futures.add(pool.submit(() -> { semaphore.acquire(); try { Thread.sleep(100); return "plik"+id; } finally { semaphore.release(); } })); }
for (Future<String> f : futures) System.out.println(f.get());
pool.shutdown(); pool.awaitTermination(5, TimeUnit.SECONDS);

int[] dane = new int[100];
for (int i=0;i<100;i++) dane[i]=i+1;
long[] sumy = new long[4];
CountDownLatch latch = new CountDownLatch(4);
for (int w=0;w<4;w++) { int watekId=w; new Thread(() -> { long suma=0; for (int i=watekId*25;i<(watekId+1)*25;i++) suma+=dane[i]; sumy[watekId]=suma; latch.countDown(); }).start(); }
latch.await(5, TimeUnit.SECONDS);
long total = 0; for (long s : sumy) total+=s;
System.out.println(total == 100L*101/2);

List<String> pula = Collections.synchronizedList(new ArrayList<>(List.of("polaczenie-A","polaczenie-B","polaczenie-C")));
Semaphore semaphore = new Semaphore(3);
for (int i=1;i<=8;i++) { int id=i; new Thread(() -> { try { semaphore.acquire(); String obiekt; synchronized (pula) { obiekt = pula.remove(0); } System.out.println("watek-"+id+" uzywa "+obiekt); Thread.sleep(50+new Random().nextInt(50)); synchronized (pula) { pula.add(obiekt); } } catch (Exception e) {} finally { semaphore.release(); } }).start(); }

CyclicBarrier barrier = new CyclicBarrier(4);
new Thread(() -> { try { Thread.sleep(2000); barrier.await(); } catch (Exception e) {} }).start();
for (int i=1;i<=3;i++) { int id=i; new Thread(() -> { try { barrier.await(500, TimeUnit.MILLISECONDS); } catch (java.util.concurrent.TimeoutException | BrokenBarrierException e) { System.out.println(id+": bariera przerwana przez zbyt wolny watek"); } catch (Exception e) {} }).start(); }

CountDownLatch prepareLatch = new CountDownLatch(4);
CountDownLatch commitLatch = new CountDownLatch(1);
for (int i=1;i<=4;i++) { int id=i; new Thread(() -> { System.out.println("uczestnik-"+id+": gotowy do zatwierdzenia"); prepareLatch.countDown(); try { commitLatch.await(); System.out.println("uczestnik-"+id+": zatwierdzone"); } catch (Exception e) {} }).start(); }
prepareLatch.await(5, TimeUnit.SECONDS);
System.out.println("faza commit");
commitLatch.countDown();

List<Integer> bufor = Collections.synchronizedList(new LinkedList<>());
Semaphore emptySlots = new Semaphore(5);
Semaphore fullSlots = new Semaphore(0);
Thread producent = new Thread(() -> { for (int i=1;i<=20;i++) { try { emptySlots.acquire(); bufor.add(i); fullSlots.release(); } catch (Exception e) {} } });
List<Integer> odebrane = Collections.synchronizedList(new ArrayList<>());
Thread konsument = new Thread(() -> { for (int i=0;i<20;i++) { try { fullSlots.acquire(); odebrane.add(((LinkedList<Integer>)bufor).remove(0)); emptySlots.release(); } catch (Exception e) {} } });
producent.start(); konsument.start();
producent.join(5_000); konsument.join(5_000);
System.out.println(odebrane.size() == 20);

CountDownLatch startGate = new CountDownLatch(1);
CyclicBarrier checkpoint = new CyclicBarrier(5);
CountDownLatch finishGate = new CountDownLatch(5);
ExecutorService pool = Executors.newFixedThreadPool(5);
for (int i=1;i<=5;i++) { int id=i; pool.submit(() -> { try { startGate.await(); Thread.sleep(50+new Random().nextInt(100)); System.out.println(id+": dotarl do checkpointu"); checkpoint.await(); Thread.sleep(50+new Random().nextInt(100)); System.out.println(id+": dobiegl do mety"); } catch (Exception e) {} finally { finishGate.countDown(); } }); }
startGate.countDown();
finishGate.await(5, TimeUnit.SECONDS);
pool.shutdown(); pool.awaitTermination(5, TimeUnit.SECONDS);

class SimpleLatch {
    private int count;
    SimpleLatch(int count) { this.count = count; }
    synchronized void countDown() { if (count > 0) { count--; if (count == 0) notifyAll(); } }
    synchronized void await() throws InterruptedException { while (count > 0) wait(); }
}
SimpleLatch simpleLatch = new SimpleLatch(4);
for (int i=0;i<4;i++) new Thread(simpleLatch::countDown).start();
simpleLatch.await();
System.out.println("SimpleLatch: wszyscy gotowi");

Semaphore loadSlots = new Semaphore(2);
CountDownLatch modulesLoaded = new CountDownLatch(6);
CyclicBarrier validationBarrier = new CyclicBarrier(6, () -> System.out.println("walidacja zakonczona"));
ExecutorService pool = Executors.newFixedThreadPool(6);
for (int i=1;i<=6;i++) { int id=i; pool.submit(() -> {
    try { loadSlots.acquire(); System.out.println("modul-"+id+": laduje sie"); Thread.sleep(100); } catch (Exception e) {} finally { loadSlots.release(); modulesLoaded.countDown(); }
    try { modulesLoaded.await(5, TimeUnit.SECONDS); validationBarrier.await(5, TimeUnit.SECONDS); } catch (Exception e) {}
}); }
pool.shutdown(); pool.awaitTermination(10, TimeUnit.SECONDS);
System.out.println("system gotowy");
